const names = {en:'English', es:'Español', it:'Italiano', de:'Deutsch', nl:'Nederlands',
  'zh-Hant':'繁體中文', 'zh-Hans':'简体中文', uk:'Українська', ru:'Русский', ar:'العربية', fr:'Français', pl:'Polski'};
const letterTitles = {
  es: year => `Carta a los sacerdotes para el Jueves Santo de ${year}`,
  it: year => `Lettera ai sacerdoti per il Giovedì Santo del ${year}`,
  de: year => `Schreiben an die Priester zum Gründonnerstag ${year}`,
  nl: year => `Brief aan de priesters voor Witte Donderdag ${year}`,
  'zh-Hant': year => `${year}年聖週四致司鐸書`,
  'zh-Hans': year => `${year}年圣周四致司铎书`,
  uk: year => `Лист до священників на Великий четвер ${year} року`,
  ru: year => `Письмо священникам к Великому четвергу ${year} года`,
  ar: year => `رسالة إلى الكهنة بمناسبة خميس الأسرار سنة ${year}`,
  fr: year => `Lettre aux prêtres pour le Jeudi saint ${year}`,
  pl: year => `List do kapłanów na Wielki Czwartek ${year} roku`,
};
const exhortationSubtitles = {
  es:'La formación de los sacerdotes', it:'La formazione dei sacerdoti',
  de:'Die Priesterausbildung', nl:'De vorming van priesters',
  'zh-Hant':'我要給你們牧者', 'zh-Hans':'我要给你们牧者',
  uk:'Формація священників', ru:'Подготовка священников', ar:'تنشئة الكهنة',
  fr:'La formation des prêtres', pl:'Formacja kapłanów',
};
const noteLabels = {
  en:'Footnotes', es:'Notas', it:'Note', de:'Anmerkungen', nl:'Voetnoten',
  'zh-Hant':'註釋', 'zh-Hans':'注释', uk:'Примітки', ru:'Примечания', ar:'الحواشي', fr:'Notes', pl:'Przypisy',
};
const translationNotices = {
  en:['This unofficial SACERDOS translation was generated by AI and may contain errors.', 'Read the source text'],
  es:['Esta traducción no oficial de SACERDOS se ha generado con inteligencia artificial y puede contener errores.', 'Leer el texto fuente'],
  it:['Questa traduzione non ufficiale di SACERDOS è stata generata con l’intelligenza artificiale e può contenere errori.', 'Leggi il testo di partenza'],
  de:['Diese inoffizielle SACERDOS-Übersetzung wurde mit KI erstellt und kann Fehler enthalten.', 'Ausgangstext lesen'],
  nl:['Deze onofficiële SACERDOS-vertaling is gemaakt met AI en kan fouten bevatten.', 'Lees de brontekst'],
  'zh-Hant':['此為 SACERDOS 使用人工智慧生成的非官方譯文，可能含有錯誤。', '閱讀來源文本'],
  'zh-Hans':['此为 SACERDOS 使用人工智能生成的非官方译文，可能含有错误。', '阅读来源文本'],
  uk:['Цей неофіційний переклад SACERDOS створено за допомогою штучного інтелекту. Він може містити помилки.', 'Читати текст джерела'],
  ru:['Этот неофициальный перевод SACERDOS выполнен с помощью искусственного интеллекта и может содержать ошибки.', 'Читать исходный текст'],
  ar:['هذه ترجمة غير رسمية أعدّها SACERDOS باستخدام الذكاء الاصطناعي، وقد تتضمّن أخطاء.', 'اقرأ النص المصدر'],
  fr:['Cette traduction non officielle de SACERDOS a été générée par intelligence artificielle et peut contenir des erreurs.', 'Lire le texte source'],
  pl:['Ten nieoficjalny przekład SACERDOS został wygenerowany z użyciem sztucznej inteligencji i może zawierać błędy.', 'Przeczytaj tekst źródłowy'],
};
const el = id => document.getElementById(id);
const select = el('locale');
const query = el('query');
const results = el('results');
const reader = el('reader');
const status = el('status');
const position = new Map();
let catalog;
let texts;
let previousDocument;
let index = [];
let indexedLocale;

function element(tag, content, className) {
  const node = document.createElement(tag);
  node.textContent = content;
  if (className) node.className = className;
  return node;
}

function link(label, href) {
  const node = element('a', label);
  node.href = href;
  return node;
}

function displayTitle(doc, locale) {
  if (doc.kind === 'priests-letter') {
    return letterTitles[locale]?.(doc.year) ?? doc.title;
  }
  const subtitle = exhortationSubtitles[locale];
  if (!subtitle) return doc.title;
  if (locale.startsWith('zh')) return `${subtitle} · ${doc.title}`;
  return `${doc.title} · ${subtitle}`;
}

function setTitleLanguage(node, locale) {
  node.lang = locale;
  node.dir = locale === 'ar' ? 'rtl' : 'auto';
}

function route(id, locale, passage) {
  const params = new URLSearchParams({doc:id, lang:locale});
  if (passage !== undefined) params.set('p', passage);
  return '#' + params;
}

function fold(text, locale) {
  const lowercase = text.toLocaleLowerCase(locale);
  const normalized = (locale === 'pl' ? lowercase.replaceAll('ł', 'l') : lowercase).normalize('NFKC');
  if (locale.startsWith('zh')) return normalized.replace(/\s+/gu, '');
  return normalized.normalize('NFD').replace(/\p{M}/gu, '').replace(/\s+/gu, ' ').trim();
}

function snippet(text, needle, locale) {
  if (text.length <= 240) return text;
  const index = Math.max(0, fold(text, locale).indexOf(needle));
  const start = Math.max(0, index - 65);
  const end = Math.min(text.length, start + 235);
  return (start ? '…' : '') + text.slice(start, end) + (end < text.length ? '…' : '');
}

function localeIndex(locale) {
  if (indexedLocale === locale) return index;
  indexedLocale = locale;
  index = catalog.entries.flatMap(doc => {
    const text = texts[doc.id + '/' + locale];
    if (!text) return [];
    const title = displayTitle(doc, locale);
    return [{doc, text:title, search:fold(title, locale)}, ...text.passages.map((part, p) =>
      ({doc, p, text:part.text, search:fold(part.text, locale)}))];
  });
  return index;
}

function row(doc, locale, detail, passage) {
  const article = element('article', '', 'entry' + (doc.kind === 'priests-letter' ? '' : ' featured'));
  const heading = element('h3', '');
  heading.append(link(displayTitle(doc, locale), route(doc.id, locale, passage)));
  setTitleLanguage(heading, locale);
  const body = element('div', '');
  body.append(heading, detail);
  article.append(element('span', doc.year, 'year'), body);
  return article;
}

function readingNotes(text, locale) {
  const groups = text.noteGroups ?? [];
  const lookup = groups.map(group => new Map(group.notes.map(note => [note.number, note.text])));
  const dialog = element('dialog', '', 'note-dialog');
  const dialogTitle = element('h2', '');
  dialogTitle.id = 'note-title';
  dialog.setAttribute('aria-labelledby', dialogTitle.id);
  const noteText = element('p', '');
  const close = element('button', '×');
  close.setAttribute('aria-label', 'Close');
  close.onclick = () => dialog.close();
  dialog.append(close, dialogTitle, noteText);
  setTitleLanguage(dialog, locale);
  const panel = element('details', '', 'footnotes');
  panel.append(element('summary', noteLabels[locale]));
  setTitleLanguage(panel, locale);
  for (const group of groups) {
    if (group.title) panel.append(element('h3', group.title));
    const list = element('ol', '');
    for (const note of group.notes) {
      const item = element('li', note.text);
      if (note.number === '*') {
        item.className = 'star-note';
        item.prepend('* ');
      } else {
        item.value = Number(note.number);
      }
      list.append(item);
    }
    panel.append(list);
  }
  return {
    appendTo(parent) {
      if (groups.length) parent.append(panel, dialog);
    },
    render(block, part) {
      const notes = lookup[part.noteGroup === undefined ? 0 : part.noteGroup];
      if (!notes) return;
      const markers = /\[(\p{Nd}+)\]|[（(](\p{Nd}+)[）)]|(?<=[\p{L}\p{P}])([*])/gu;
      let offset = 0;
      for (const marker of part.text.matchAll(markers)) {
        const number = (marker[1] ?? marker[2] ?? marker[3]).normalize('NFKC')
          .replace(/[٠-٩]/g, digit => String(digit.charCodeAt(0) - 0x660))
          .replace(/[۰-۹]/g, digit => String(digit.charCodeAt(0) - 0x6f0));
        if (!notes.has(number)) continue;
        if (offset === 0) block.replaceChildren();
        block.append(part.text.slice(offset, marker.index));
        const reference = element('sup', '');
        const button = element('button', number);
        button.setAttribute('aria-label', noteLabels[locale] + ' ' + number);
        button.onclick = () => {
          dialogTitle.textContent = noteLabels[locale] + ' ' + number;
          noteText.textContent = notes.get(number);
          dialog.showModal();
        };
        reference.append(button);
        block.append(reference);
        offset = marker.index + marker[0].length;
      }
      if (offset) block.append(part.text.slice(offset));
    },
  };
}

function renderLibrary() {
  const locale = select.value;
  const available = catalog.entries.filter(doc => texts[doc.id + '/' + locale]).length;
  const needle = fold(query.value, locale);
  el('view-title').textContent = needle ? 'Search results' : 'Collection';
  if (needle) {
    const matches = localeIndex(locale).filter(item => item.search.includes(needle));
    status.textContent = available ? matches.length + ' matches across ' + available + ' searchable editions' : 'No indexed editions in ' + names[locale];
    const cards = matches.slice(0, 150).map(({doc, p, text}) => {
      const preview = element('p', snippet(text, needle, locale));
      preview.lang = locale;
      preview.dir = 'auto';
      return row(doc, locale, preview, p);
    });
    if (!cards.length) cards.push(element('p', available ? 'No passages match this search.' : 'Choose a reading language with indexed editions.', 'notice'));
    if (matches.length > 150) cards.push(element('p', 'Showing the first 150 matches. Refine the search to narrow the results.', 'notice'));
    results.replaceChildren(...cards);
    return;
  }
  status.textContent = available + ' of ' + catalog.entries.length + ' editions readable in ' + names[locale];
  const ordered = [...catalog.entries].sort((a,b) => Number(a.kind === 'priests-letter') - Number(b.kind === 'priests-letter') || a.year - b.year);
  results.replaceChildren(...ordered.map(doc => {
    const edition = doc.editions.find(item => item.locale === locale);
    const info = texts[doc.id + '/' + locale] ? 'Read in ' + names[locale]
      : edition ? 'Edition unavailable in the reader' : 'No catalog edition in ' + names[locale];
    return row(doc, locale, element('p', info, 'meta'));
  }));
}

function renderRoute() {
  const params = new URLSearchParams(location.hash.slice(1));
  const doc = catalog.entries.find(item => item.id === params.get('doc'));
  const locale = Object.hasOwn(names, params.get('lang')) ? params.get('lang') : select.value;
  reader.hidden = !doc;
  el('library').hidden = Boolean(doc);

  if (!doc) {
    renderLibrary();
    if (previousDocument) window.scrollTo(0, position.get(previousDocument) ?? 0);
    previousDocument = null;
    return;
  }
  if (!previousDocument) position.set(doc.id, window.scrollY);
  previousDocument = doc.id;
  select.value = locale;
  const back = link('Back to collection', '#');
  const head = element('div', '', 'reader-head');
  const title = element('h1', displayTitle(doc, locale));
  setTitleLanguage(title, locale);
  head.append(element('p', doc.year + ' · Saint John Paul II', 'eyebrow'), title);
  const sources = element('div', '', 'sources');
  const edition = doc.editions.find(item => item.locale === locale);
  if (edition?.format === 'pdf') sources.append(link('Open source PDF', edition.url));
  head.append(element('p', names[locale], 'meta'), sources);
  reader.replaceChildren(back, head);

  const other = catalog.targetContentLocales.filter(language => language !== locale &&
    (texts[doc.id + '/' + language] || doc.editions.some(item => item.locale === language)));
  if (other.length) {
    const options = element('div', '', 'sources');
    options.setAttribute('aria-label', 'Other editions');
    for (const language of other) options.append(link(names[language], route(doc.id, language)));
    head.append(options);
  }
  const text = texts[doc.id + '/' + locale];
  if (text) {
    if (text.translation?.type === 'ai-generated') {
      const [disclaimer, label] = translationNotices[locale];
      const notice = element('p', disclaimer + ' ', 'notice');
      setTitleLanguage(notice, locale);
      notice.append(link(label, text.source));
      reader.append(notice);
    }
    const notes = readingNotes(text, locale);
    const body = element('article', '', 'reader-body');
    body.lang = locale;
    body.dir = 'auto';
    text.passages.forEach((part, i) => {
      const block = element(part.heading ? 'h2' : 'p', part.text);
      block.id = 'passage-' + i;
      notes.render(block, part);
      body.append(block);
    });
    reader.append(body);
    notes.appendTo(reader);
    const target = document.getElementById('passage-' + params.get('p'));
    if (target) {
      target.classList.add('match');
      target.tabIndex = -1;
      target.focus({preventScroll:true});
      target.scrollIntoView({block:'start'});
      return;
    }
  } else {
    reader.append(element('p', edition ? 'This edition is currently unavailable in the reader.' : 'The source catalog has no verified edition in this language.', 'notice'));
  }
  title.tabIndex = -1;
  title.focus({preventScroll:true});
  window.scrollTo(0, 0);
}

async function load(path) {
  const response = await fetch(path);
  if (!response.ok) throw new Error('Could not load ' + path);
  return response.json();
}

try {
  [catalog, texts] = await Promise.all([load('./sacerdos-source-catalog.json'), load('./editions.json')]);
  select.replaceChildren(...catalog.targetContentLocales.map(locale => new Option(names[locale], locale)));
  try {
    const stored = localStorage.getItem('sacerdos-language');
    if (Object.hasOwn(names, stored)) select.value = stored;
  } catch {}
  select.addEventListener('change', () => {
    try { localStorage.setItem('sacerdos-language', select.value); } catch {}
    renderLibrary();
  });
  query.addEventListener('input', renderLibrary);
  addEventListener('hashchange', renderRoute);
  renderRoute();
} catch (error) {
  status.textContent = 'The collection could not be loaded. Reload to try again.';
  console.error(error);
}

const updateNetwork = () => { el('offline').hidden = navigator.onLine; };
addEventListener('online', updateNetwork);
addEventListener('offline', updateNetwork);
updateNetwork();
addEventListener('beforeinstallprompt', event => {
  event.preventDefault();
  const install = el('install');
  install.hidden = false;
  install.onclick = async () => {
    await event.prompt();
    install.hidden = true;
  };
});
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('./sw.js').catch(console.error);
}
